<template><div class="page"><h2>FMECA 管理</h2><el-button type="primary" @click="add">新增记录</el-button><el-button @click="save">保存全部</el-button><el-table :data="rows" style="margin-top:16px"><el-table-column label="部件"><template #default="s"><el-input v-model="s.row.component"/></template></el-table-column><el-table-column label="故障模式"><template #default="s"><el-input v-model="s.row.mode"/></template></el-table-column><el-table-column label="原因"><template #default="s"><el-input v-model="s.row.cause"/></template></el-table-column><el-table-column label="风险"><template #default="s"><el-select v-model="s.row.level"><el-option label="高" value="高"/><el-option label="中" value="中"/><el-option label="低" value="低"/></el-select></template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="danger" @click="rows.splice(s.$index,1)">删除</el-button></template></el-table-column></el-table></div></template>
<script setup>import{ref,onMounted}from'vue';import{ElMessage}from'element-plus';const rows=ref([]);async function load(){const r=await fetch('/api/v1/knowledge/fmeca/');const d=await r.json();rows.value=d[0]?.data||[]}function add(){rows.value.push({component:'',mode:'',cause:'',level:'中'})}async function save(){const r=await fetch('/api/v1/knowledge/fmeca/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:rows.value})});if(r.ok)ElMessage.success('FMECA已保存')}onMounted(load)</script><style scoped>.page{max-width:1300px}.el-button{margin-right:8px}</style>
